import {test,expect} from "./export-test";
import {mkdtemp,readFile,rm} from "node:fs/promises";
import {tmpdir} from "node:os";
import path from "node:path";
import {execFileSync} from "node:child_process";

// Actual offline text-to-speech fixture is generated by the CI runner.
// ASR result is NOT mocked: Chromium must load the site's local ONNX Whisper
// model, recognize the audible speech and export timed subtitle files.
test("Whisper Tiny real inference recognizes synthetic English speech and writes genuine timed SRT/VTT",async({page})=>{
 test.setTimeout(300000);
 const temp=await mkdtemp(path.join(tmpdir(),"lingxifield-real-asr-"));
 try{
  const wavPath=path.join(temp,"speech.wav");
  execFileSync("espeak-ng",["-v","en-us","-s","145","-w",wavPath,"The blue planet Earth has mountains and rivers."],{timeout:15000});
  const wav=await readFile(wavPath);
  expect(wav.subarray(0,4).toString("ascii")).toBe("RIFF");
  expect(wav.byteLength).toBeGreaterThan(5000);
  let q:any;
  await page.route("**/api/tools/quote",r=>{
   if(r.request().method()!=="POST")return r.fulfill({status:404,body:"NOT_USED"});
   const body=r.request().postDataJSON();
   expect(body.toolId).toBe("audio-transcription");
   q={id:"isolated-real-asr",tool_id:body.toolId,quantity:body.quantity,unit_name:"minute",amount_rmb:1,amount_usd:1,display_amount:1,display_currency:body.currency,currency:body.currency,metadata:body.metadata,expires_at:new Date(Date.now()+3600000).toISOString()};
   return r.fulfill({json:q});
  });
  await page.route("**/api/tools/pay/status**",r=>r.fulfill({json:{paid:true,quote:{tool_id:"audio-transcription",quantity:q?.quantity,metadata:q?.metadata}}}));
  const telemetry:string[]=[];
  page.on("pageerror",e=>telemetry.push("PAGE:"+e.message.slice(0,280)));
  page.on("console",m=>{if(m.type()==="error"||m.type()==="warning")telemetry.push("CONSOLE:"+m.text().slice(0,350))});
  page.on("requestfailed",r=>{if(/models|onnx|wasm|transformers|huggingface/i.test(r.url()))telemetry.push("REQUEST:"+r.url().slice(0,180)+":"+(r.failure()?.errorText||""))});
  page.on("response",r=>{if(r.status()>=400&&/models|onnx|wasm|transformers|huggingface/i.test(r.url()))telemetry.push("HTTP:"+r.status()+":"+r.url().slice(0,250))});
  await page.goto("/tools/audio-transcription?lang=en");
  const input=page.locator('input[type="file"]').first();
  await expect(input).toBeEnabled({timeout:15000});
  await input.setInputFiles({name:"original-espeak-voice.wav",mimeType:"audio/wav",buffer:wav});
  const price=page.getByRole("button",{name:/see price|price|price this|查看价格/i}).first();
  await expect(price).toBeEnabled({timeout:20000});
  await price.click();
  await expect(page.getByRole("button",{name:"Confirm & pay",exact:true})).toBeVisible();
  await page.evaluate(()=>window.dispatchEvent(new Event("pageshow")));
  const transcript=page.locator('textarea[readonly]').first();
  // Do not burn four minutes waiting for a result if a paid-job failure
  // already surfaced. Capture the genuine browser/model condition.
  const began=Date.now();
  while(Date.now()-began<150000){
   if(await transcript.isVisible())break;
   const retryButton=page.getByRole("button",{name:/Resume paid task|Retry the result/i});
   // The Resume button is present but DISABLED while inference is actually running.
   // Its presence alone is not a failure signal; only an enabled retry means processing stopped.
   const retry=await retryButton.isVisible()&&await retryButton.isEnabled();
   const alerts=await page.locator('[role="alert"]').allTextContents();
   if(retry||alerts.some(x=>/failed|could not|unavailable|失败|无法|暂时/i.test(x))){
    const details={retry,alerts,telemetry:telemetry.slice(-35)};
    throw new Error("REAL_WHISPER_ASR_FAILED:"+JSON.stringify(details));
   }
   await page.waitForTimeout(1000);
  }
  if(!await transcript.isVisible()){
   const details={alerts:await page.locator('[role="alert"]').allTextContents(),status:await page.locator('[role="status"]').allTextContents(),body:(await page.locator("main").innerText()).slice(-1400),telemetry:telemetry.slice(-45)};
   throw new Error("REAL_WHISPER_TIMEOUT:"+JSON.stringify(details));
  }
  const recognized=await transcript.inputValue();
  expect(recognized.length).toBeGreaterThan(8);
  expect(recognized.toLowerCase()).toMatch(/earth|planet|mountain|river/);
  const files=page.getByTestId("result-file-actions");
  await expect(files).toHaveCount(3,{timeout:15000});
  for(const [index,ext,expectedTime] of [[0,"txt",false],[1,"srt",true],[2,"vtt",true]] as const){
   const download=page.waitForEvent("download");
   await files.nth(index).getByRole("button",{name:"Save file",exact:true}).click();
   const item=await download;
   expect(item.suggestedFilename()).toBe("lingxifield-transcript."+ext);
   expect(await item.failure()).toBeNull();
   const bytes=await readFile((await item.path())!);
   const text=bytes.toString("utf8");
   expect(text.toLowerCase()).toMatch(/earth|planet|mountain|river/);
   if(expectedTime)expect(text).toMatch(/00:00:\d{2}[,.]\d{3} --> 00:00:\d{2}[,.]\d{3}/);
   if(ext==="vtt")expect(text).toMatch(/^WEBVTT\n\n/);
  }
 }finally{await rm(temp,{recursive:true,force:true})}
});
